  -- ks2-25-stay-the-maker
  perform pg_temp.gc_set('ks2-25-stay-the-maker', 'teacher_notes', '{"prior_knowledge",1}', 'e3f378c5b8e1a4925ccb30c2ccc87291', null, $gc393$"Children can say where an AI picture really comes from, and that I made this with an AI tool is the honest line, from ks2-09."$gc393$::jsonb);
  perform pg_temp.gc_set('ks2-25-stay-the-maker', 'slides', '{6,"script"}', '5c45d4d5a3dd5d3edfdc350a5d123e06', null, $gc393$"Hands down, three seconds of thinking time, then fingers up, one, two or three, everyone at once. The options shuffle on every run, so name them by their words. Most of the class will say it was your idea, and you must not squash it. Their idea is real. Say that first, then separate having the idea from doing the making. That separation is the lesson. If they did the copyright lesson, I made this with an AI tool is still the honest line. Today asks who did the making."$gc393$::jsonb);
  perform pg_temp.gc_set('ks2-25-stay-the-maker', 'assessment', '{"teacher_judgement"}', null, null, $gc393${"scale":["secure","developing","revisit"],"descriptors":{"secure":"Turns a do it all ask into a help me ask and explains a piece of work back with the book shut.","developing":"Sorts helper from took over on the cards but cannot yet say what the job was on their own work.","revisit":"Says I made it because I asked for it, or hears the lesson as a rule against using a helper."}}$gc393$::jsonb);

